import {eventModel,subscriberModel,radioModel} from './models.mjs';
const map={subscribers:{form:'subscriber-model',calc:subscriberModel},inventory:{form:'radio-model',calc:radioModel},events:{form:'event-model',calc:eventModel}};
const scenario={
'subscriber-model':{friction:{people:10000,price:600,retention:40,costshare:55,service:30,cac:260},base:{people:10000,price:600,retention:50,costshare:55,service:30,cac:180},post:{people:10000,price:600,retention:60,costshare:55,service:30,cac:130}},
'radio-model':{pressure:{seconds:100000,utilisation:65,yield:100,newutil:75,discount:15},base:{seconds:100000,utilisation:70,yield:100,newutil:80,discount:10},protect:{seconds:100000,utilisation:75,yield:100,newutil:82,discount:2}},
'event-model':{weak:{capacity:5000,occupancy:40,ticket:800,sponsor:600000,ancillary:100000,fixed:3000000,variable:150},base:{capacity:5000,occupancy:60,ticket:800,sponsor:1500000,ancillary:100000,fixed:3000000,variable:150},strong:{capacity:5000,occupancy:85,ticket:850,sponsor:1600000,ancillary:100000,fixed:3000000,variable:150}}};
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
function syncRangeOutputs(){for(const range of document.querySelectorAll('.lab-range')){const output=document.getElementById(range.id+'-value');if(!output)continue;output.textContent=(range.id==='cac'?'₹':'')+range.value+(['retention','utilisation','discount','occupancy'].includes(range.id)?'%':'')}}
function updateTakeaways(){syncRangeOutputs();for(const [id,settings] of Object.entries(map)){const form=document.getElementById(settings.form),target=document.getElementById(id+'-takeaway');if(!form||!target)continue;const inputs=[...form.querySelectorAll('input')];if(inputs.some(el=>!el.checkValidity()||el.value==='')){target.textContent='Enter valid assumptions to see the decision.';continue}const v=Object.fromEntries(inputs.map(el=>[el.name,Number(el.value)]));const result=settings.calc(v);if(id==='subscribers')target.textContent='Illustrative Year-one contribution: '+money(result.firstYear)+'. Next-year renewal contribution: '+money(result.renewalContribution)+'. Renewal does not change prepaid Year-one revenue.';else if(id==='inventory')target.textContent=(result.delta>=0?'Illustrative revenue increases by ':'Illustrative revenue decreases by ')+money(Math.abs(result.delta))+'. '+(result.required===null||result.required>100?'Matching the starting revenue would exceed available airtime.':'Verify incremental costs and listener ad load before discounting.');else target.textContent='Illustrative event contribution: '+money(result.contribution)+'. '+(result.breakEven===null?'Break-even cannot be reached through extra tickets at this ticket margin.':result.withinCapacity?'Break-even needs '+result.breakEven.toLocaleString('en-IN')+' paid attendees.':'Break-even exceeds ticket capacity.')} }
for(const v of Object.values(map))document.getElementById(v.form)?.addEventListener('input',()=>{document.querySelectorAll('.lab-preset[data-model="'+v.form+'"]').forEach(b=>b.classList.remove('active'));updateTakeaways()});
document.querySelectorAll('.lab-preset').forEach(b=>b.addEventListener('click',()=>{const form=document.getElementById(b.dataset.model),values=scenario[b.dataset.model]?.[b.dataset.preset];if(!form||!values)return;for(const [name,value] of Object.entries(values)){const i=form.elements.namedItem(name);if(i)i.value=value;}form.dispatchEvent(new Event('input',{bubbles:true}));document.querySelectorAll('.lab-preset[data-model="'+b.dataset.model+'"]').forEach(el=>el.classList.toggle('active',el===b));updateTakeaways()}));
document.querySelectorAll('.lab-model').forEach(form=>form.addEventListener('reset',()=>setTimeout(updateTakeaways,0)));
const tabs=[...document.querySelectorAll('[role="tab"][data-tab]')];function activate(id,focus=false){for(const tab of tabs){const on=tab.dataset.tab===id;tab.setAttribute('aria-selected',String(on));tab.tabIndex=on?0:-1;document.getElementById(tab.dataset.tab).hidden=!on;if(on&&focus)tab.focus();}}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>{activate(tab.dataset.tab);history.replaceState(null,'','#'+tab.dataset.tab)});tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activate(tabs[next].dataset.tab,true);history.replaceState(null,'','#'+tabs[next].dataset.tab)})});
function selectHash(){const id=location.hash.slice(1);if(map[id]){activate(id);document.getElementById(id)?.scrollIntoView({block:'start'})}}window.addEventListener('hashchange',selectHash);selectHash();updateTakeaways();